                It.Is<It.IsAnyType>((v, t) => v.ToString().Contains("Process sequentially done")),
                It.IsAny<Exception>(),
                It.Is<Func<It.IsAnyType, Exception, string>>((v, t) => true)),
            Times.Once);
    }
}
